#include <iostream>
#include <string>

int main()
{
    std::string pathname = ".././my/file/./text";
    std::string curdir = ".";
    std::string pardir = "..";

    std::string ::size_type size;
    size = pathname.find(curdir);
    while(size != pathname.npos)
    { 
        // replace "." or space with ""(empty string)        
        pathname.replace(size, curdir.size(), "");     
        // move to the next '.' that starts with same index as the current one
        size = pathname.find(curdir, size + 1);
    }
    size = pathname.find(pardir);
    while(size != pathname.npos)
    {
        // replace ".."
        pathname.replace(size, pardir.size(), "/");
        size = pathname.find(pardir, size + 1);
        // if there is a `/' after the `..', find the `/' and replace it with ''
        size = pathname.find("/", size);
        if(size != pathname.npos)
            pathname.replace(size, 1, "");
    }      
    if(pathname[0] == '/')
        pathname.erase(0,1);
    std::cout << pathname << std::endl;
    return 0;
}

